s_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2603.18073", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2603.18073", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2603.18073", "pdf_url": "https://arxiv.org/pdf/2603.18073", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Modern language model-based AI systems are remarkably powerful, yet their capabilities remain fundamentally capped by their human creators in three key ways. First, although a model's weights can be updated via fine-tuning, acquiring new knowledge from small, specialized corpora after pretraining remains highly data-inefficient. Second, the training of these systems relies heavily on finite, human-generated data from across history. Third, the pipelines used to train AI models are confined by the algorithms that human researchers can discover and explore. This thesis takes a small step toward overcoming these inherent limitations, presenting three chapters aimed at breaking these dependencies to create continually self-improving AI. First, to overcome this data-efficiency barrier in knowledge acquisition, we propose a synthetic data approach that diversifies and amplifies small corpora into rich knowledge representations, enabling a model to effectively update its parameters from limited source material. Second, to reduce reliance on human data, we show that given a fixed amount of such data, the model can self-generate synthetic data to bootstrap its fundamental pretraining capabilities without distillation from any off-the-shelf, instruction-tuned LM. Finally, to transcend human-engineered training paradigms, we demonstrate that by scaling search during test time over the space of algorithms, AI can search over a larger space of learning algorithm configurations than human researchers can explore manually."}]", "excerpt_truncated": true, "source_sha256": "1248d20a42f0ae48439b98b88389187e3e6bed74a5f4be15b7ed90217bbaee26", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.48550/arxiv.2502.09858", "openalex:W4407632372", "arxiv:2502.09858", "arxiv:2603.18073"], "source_candidates": ["https://doi.org/10.48550/arxiv.2502.09858", "https://arxiv.org/pdf/2502.09858", "https://arxiv.org/pdf/2603.18073"], "source_candidate_identities": {}}

